/* CSS PART 1 OF 2 */

/* Design tokens */
:root {
  color-scheme: light;
  --ink: #202b32;
  --ink-soft: #53616a;
  --navy: #182d3b;
  --navy-deep: #10212d;
  --blue: #365e72;
  --blue-light: #e9f0f2;
  --copper: #bd7549;
  --copper-dark: #985737;
  --paper: #f7f6f2;
  --white: #ffffff;
  --line: #dce1df;
  --muted: #eef0ed;
  --font-heading: "Montserrat", "Arial", sans-serif;
  --font-body: "Inter", "Helvetica Neue", sans-serif;
  --container: 1180px;
  --gutter: clamp(20px, 5vw, 64px);
  --radius: 5px;
  --shadow: 0 18px 50px rgba(16, 33, 45, 0.12);
}

/* Reset and foundations */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

::selection {
  color: var(--white);
  background: var(--blue);
}

/* Shared typography */
h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--navy);
  font-family: var(--font-heading);
  font-weight: 750;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  max-width: 760px;
  font-size: clamp(2.8rem, 5.8vw, 5.25rem);
}

h2 {
  font-size: clamp(2rem, 3.8vw, 3.35rem);
}

h3 {
  font-size: 1.3rem;
  letter-spacing: -0.02em;
}

p {
  margin: 0 0 1.15rem;
}

p:last-child {
  margin-bottom: 0;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 19px;
  color: var(--copper-dark);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 27px;
  height: 2px;
  background: var(--copper);
  content: "";
}

.section-intro {
  max-width: 670px;
  margin-bottom: 44px;
}

.section-intro p {
  max-width: 590px;
  margin-top: 18px;
  color: var(--ink-soft);
  font-size: 1.05rem;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--copper-dark);
  font-weight: 750;
  transition: color 180ms ease, gap 180ms ease;
}

.text-link:hover {
  gap: 14px;
  color: var(--navy);
}

/* Page layout */
.container {
  width: min(calc(100% - var(--gutter) * 2), var(--container));
  margin-inline: auto;
}

.section {
  padding-block: clamp(76px, 9vw, 122px);
}

.section--white {
  background: var(--white);
}

.section--dark {
  background: var(--navy);
  color: rgba(255, 255, 255, 0.78);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark .eyebrow {
  color: #e5ad85;
}

.section--dark .section-intro p {
  color: rgba(255, 255, 255, 0.72);
}

/* Header and navigation */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 43, 50, 0.09);
}

.header-inner {
  display: flex;
  min-height: 91px;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
}

.brand-logo {
  width: 67px;
  height: 67px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.brand-name {
  color: var(--navy);
  font-family: var(--font-heading);
  font-size: 0.93rem;
  font-weight: 850;
  line-height: 1.25;
  letter-spacing: -0.025em;
}

.brand-description {
  color: var(--ink-soft);
  font-size: 0.67rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(17px, 2.5vw, 33px);
}

.primary-nav a:not(.button) {
  color: var(--ink);
  font-size: 0.82rem;
  font-weight: 650;
  transition: color 180ms ease;
}

.primary-nav a:not(.button):hover {
  color: var(--copper-dark);
}

.header-phone {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.header-phone small {
  color: var(--ink-soft);
  font-size: 0.65rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.header-phone strong {
  color: var(--navy);
  font-size: 0.95rem;
  font-weight: 800;
}

/* Reusable buttons */
.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 11px;
  padding: 13px 23px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--copper);
  color: var(--white);
  font-size: 0.87rem;
  font-weight: 800;
  line-height: 1.25;
  text-align: center;
  transition:
    background 180ms ease,
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--copper-dark);
}

.button--dark {
  background: var(--navy);
}

.button--dark:hover {
  background: var(--navy-deep);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--navy);
}

.button--light {
  border-color: var(--line);
  background: var(--white);
  color: var(--navy);
}

.button--light:hover {
  border-color: var(--navy);
  background: var(--blue-light);
}

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--navy-deep);
  color: rgba(255, 255, 255, 0.8);
}

.hero-inner {
  display: grid;
  min-height: 640px;
  grid-template-columns: 1.03fr 0.97fr;
  align-items: center;
  gap: clamp(36px, 6vw, 80px);
  padding-block: 72px;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 620px;
}

.hero .eyebrow {
  color: #e5ad85;
}

.hero h1 {
  margin-bottom: 24px;
  color: var(--white);
}

.hero h1 span {
  color: #e4ad86;
}

.hero-description {
  max-width: 530px;
  margin-bottom: 30px;
  color: rgba(255, 255, 255, 0.76);
  font-size: clamp(1rem, 1.5vw, 1.14rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 13px;
}

.hero-image-wrap {
  position: relative;
  min-width: 0;
  height: 510px;
}

.hero-image {
  width: 100%;
  height: 100%;
  border-radius: 3px;
  object-fit: cover;
  object-position: center;
}

.hero-image-wrap::after {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(255, 255, 255, 0.17);
  content: "";
  pointer-events: none;
}

.hero-caption {
  position: absolute;
  right: -18px;
  bottom: 28px;
  z-index: 2;
  max-width: 240px;
  padding: 17px 21px;
  background: var(--white);
  box-shadow: var(--shadow);
  color: var(--navy);
  font-size: 0.82rem;
  font-weight: 750;
  line-height: 1.45;
}

.hero-caption span {
  display: block;
  margin-bottom: 4px;
  color: var(--copper-dark);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* Company credentials / positioning */
.trust-strip {
  position: relative;
  z-index: 3;
  background: var(--white);
  border-bottom: 1px solid var(--line);
}

.trust-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;
  padding-block: 26px;
}

.trust-item {
  display: flex;
  min-height: 55px;
  flex-direction: column;
  justify-content: center;
  padding-inline: 30px;
  border-right: 1px solid var(--line);
}

.trust-item:first-child {
  padding-left: 0;
}

.trust-item:last-child {
  border-right: 0;
}

.trust-item strong {
  color: var(--navy);
  font-family: var(--font-heading);
  font-size: 1.22rem;
  font-weight: 800;
  line-height: 1.3;
}

.trust-item span {
  color: var(--ink-soft);
  font-size: 0.76rem;
  font-weight: 600;
}

/* Why choose the company */
.why-grid {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: start;
  gap: clamp(45px, 8vw, 110px);
}

.why-copy {
  max-width: 510px;
}

.why-copy > p {
  margin-top: 22px;
  color: var(--ink-soft);
  font-size: 1.04rem;
}

.why-list {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--line);
}

.why-item {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 19px;
  padding-block: 23px;
  border-bottom: 1px solid var(--line);
}

.why-number {
  color: var(--copper-dark);
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 850;
  letter-spacing: 0.05em;
}

.why-item h3 {
  margin-bottom: 7px;
  font-size: 1.12rem;
}

.why-item p {
  color: var(--ink-soft);
  font-size: 0.91rem;
  line-height: 1.7;
}

/* Roofing attention section */
.roof-section {
  background: var(--blue-light);
}

.roof-layout {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  align-items: center;
  gap: clamp(42px, 7vw, 88px);
}

.roof-copy {
  max-width: 500px;
}

.roof-copy > p {
  margin-top: 19px;
  color: var(--ink-soft);
}

.roof-image-wrap {
  position: relative;
  min-width: 0;
  height: 490px;
}

.roof-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 45%;
}

.roof-checklist {
  display: grid;
  gap: 14px;
  margin: 28px 0 32px;
  padding: 0;
  list-style: none;
}

.roof-checklist li {
  position: relative;
  padding-left: 27px;
  color: var(--ink);
  font-size: 0.93rem;
  font-weight: 600;
}

.roof-checklist li::before {
  position: absolute;
  top: 0.55em;
  left: 0;
  width: 9px;
  height: 9px;
  border: 2px solid var(--copper);
  border-radius: 50%;
  content: "";
}

/* Roofing process */
.process-section {
  background: var(--navy);
}

.process-heading {
  max-width: 700px;
  margin-bottom: 49px;
}

.process-heading h2 {
  max-width: 650px;
}

.process-heading p {
  max-width: 580px;
  margin-top: 17px;
  color: rgba(255, 255, 255, 0.7);
}

.process-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.process-item {
  min-height: 215px;
  padding: 28px 30px 25px 0;
  border-right: 1px solid rgba(255, 255, 255, 0.2);
}

.process-item:not(:first-child) {
  padding-left: 30px;
}

.process-item:last-child {
  border-right: 0;
}

.process-step {
  display: block;
  margin-bottom: 27px;
  color: #e5ad85;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 850;
  letter-spacing: 0.14em;
}

.process-item h3 {
  margin-bottom: 12px;
  font-size: 1.2rem;
}

.process-item p {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9rem;
  line-height: 1.75;
}

/* Recent project portfolio */
.projects-section {
  background: var(--paper);
}

.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 44px;
}

.projects-heading .section-intro {
  margin-bottom: 0;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1.08fr 0.92fr;
  grid-template-rows: 260px 260px;
  gap: 18px;
}

.project-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--navy);
}

.project-card:first-child {
  grid-row: 1 / 3;
}

.project-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-card:hover .project-image {
  transform: scale(1.035);
}

.project-card::after {
  position: absolute;
  inset: 35% 0 0;
  background: linear-gradient(
    to bottom,
    transparent,
    rgba(16, 33, 45, 0.86)
  );
  content: "";
  pointer-events: none;
}

.project-caption {
  position: absolute;
  right: 25px;
  bottom: 23px;
  left: 25px;
  z-index: 2;
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 6px;
  color: #efbb95;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.project-caption h3 {
  color: var(--white);
  font-size: clamp(1.15rem, 2vw, 1.55rem);
}

.project-caption p {
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 0.81rem;
}
