/* CSS PART 2 OF 2 */

/* Contact and conversion */
.contact-section {
  position: relative;
  overflow: hidden;
  background: var(--navy-deep);
  color: rgba(255, 255, 255, 0.78);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 105px);
}

.contact-copy {
  max-width: 440px;
}

.contact-copy h2 {
  color: var(--white);
}

.contact-copy > p {
  margin-top: 20px;
  color: rgba(255, 255, 255, 0.74);
}

.contact-methods {
  display: grid;
  gap: 17px;
  margin-top: 35px;
}

.contact-method {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--white);
  font-weight: 700;
}

.contact-method small {
  display: block;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.72rem;
  font-weight: 600;
}

.contact-method strong {
  font-size: 1rem;
}

.contact-form {
  display: grid;
  gap: 18px;
  padding: clamp(25px, 4vw, 43px);
  background: var(--white);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.form-heading {
  margin-bottom: 8px;
}

.form-heading h3 {
  font-size: 1.65rem;
}

.form-heading p {
  margin-top: 8px;
  color: var(--ink-soft);
  font-size: 0.88rem;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.form-field {
  display: grid;
  min-width: 0;
  gap: 7px;
}

.form-field label {
  color: var(--navy);
  font-size: 0.79rem;
  font-weight: 750;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid #cbd3d4;
  border-radius: 3px;
  background: #fbfcfb;
  color: var(--ink);
  font-size: 0.9rem;
  transition: border-color 160ms ease, background 160ms ease;
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input:hover,
.form-field select:hover,
.form-field textarea:hover {
  border-color: var(--blue);
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--copper-dark);
  background: var(--white);
}

.form-submit {
  width: 100%;
  margin-top: 3px;
  cursor: pointer;
}

.form-note {
  color: var(--ink-soft);
  font-size: 0.74rem;
  line-height: 1.55;
}

/* Footer */
.site-footer {
  background: #0c1a23;
  color: rgba(255, 255, 255, 0.68);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-block: 43px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 15px;
}

.footer-brand .brand-logo {
  width: 57px;
  height: 57px;
  padding: 3px;
  border-radius: 3px;
  background: var(--white);
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, 0.62);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 22px;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.82rem;
  font-weight: 650;
}

.footer-links a:hover {
  color: #efbb95;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-block: 17px;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
  color: rgba(255, 255, 255, 0.52);
  font-size: 0.73rem;
}

/* Accessible mobile navigation control */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--white);
  color: var(--navy);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Large and medium screens */
@media (max-width: 1050px) {
  .header-inner {
    gap: 18px;
  }

  .primary-nav {
    gap: 16px;
  }

  .primary-nav a:not(.button) {
    font-size: 0.76rem;
  }

  .header-phone {
    display: none;
  }

  .hero-inner {
    min-height: 570px;
    gap: 35px;
  }

  .hero-image-wrap {
    height: 440px;
  }

  .contact-layout {
    gap: 45px;
  }
}

/* Tablet navigation and section layouts */
@media (max-width: 780px) {
  html {
    scroll-padding-top: 78px;
  }

  .header-inner {
    position: relative;
    min-height: 77px;
  }

  .brand-logo {
    width: 56px;
    height: 56px;
  }

  .brand-name {
    font-size: 0.82rem;
  }

  .brand-description {
    font-size: 0.61rem;
  }

  .menu-toggle {
    display: flex;
  }

  .primary-nav {
    position: absolute;
    top: calc(100% - 1px);
    right: 0;
    left: 0;
    display: none;
    max-height: calc(100vh - 90px);
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    overflow-y: auto;
    padding: 12px var(--gutter) 20px;
    border-top: 1px solid var(--line);
    background: var(--white);
    box-shadow: 0 14px 24px rgba(16, 33, 45, 0.12);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
    font-size: 0.91rem;
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 15px;
  }

  .hero-inner {
    min-height: auto;
    grid-template-columns: 1fr;
    gap: 38px;
    padding-block: 68px 76px;
  }

  .hero-content {
    max-width: 680px;
  }

  .hero-image-wrap {
    height: clamp(310px, 66vw, 480px);
    margin-right: 15px;
  }

  .hero-caption {
    right: -15px;
  }

  .trust-inner {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .trust-item {
    padding-inline: 16px;
  }

  .trust-item strong {
    font-size: 1.05rem;
  }

  .trust-item span {
    font-size: 0.7rem;
  }

  .why-grid,
